import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"双调·清江引张子坚运判席上","description":"","frontmatter":{"title":"双调·清江引张子坚运判席上","date":"2026-11-18T00:00:00.000Z","seq":78,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"poem_quote":false,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/双调·清江引张子坚运判席上.md","filePath":"blogs/元曲·张可久/双调·清江引张子坚运判席上.md"}'),o={name:"blogs/元曲·张可久/双调·清江引张子坚运判席上.md"};function l(c,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="双调·清江引张子坚运判席上" tabindex="-1">双调·清江引张子坚运判席上 <a class="header-anchor" href="#双调·清江引张子坚运判席上" aria-label="Permalink to &quot;双调·清江引张子坚运判席上&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">仙人掌心青数朵，山小乾坤大。</p><p class="poem-stanza">不知明月来，且向日云卧，陈抟枕头闲伴我。</p><p class="poem-stanza">飘飘落梅风正冷，缓步苍苔径。</p><p class="poem-stanza">一溪流水声，半夜扁舟兴，月明草堂人未醒。</p><p class="poem-stanza">秋风满园三径花，买得闲无价。</p><p class="poem-stanza">从前险处行，梦里说着怕，连云栈高骑瘦马。</p><p class="poem-stanza">酒边题扇华堂舞ブ画展，两行如花面。</p><p class="poem-stanza">鹅黄淡舞裙，蝶粉香歌扇，闲ㄐ玉筝罗袖卷。</p><p class="poem-stanza">昭君怨花间梦乘白玉辇，上马精神倦。</p><p class="poem-stanza">哀弹夜月情，别泪春风面，雁归不知多近远。</p><p class="poem-stanza">过刘山西风小亭黄叶多，鹤领神仙过。</p><p class="poem-stanza">云来绿树平，水迸青山破，天然图画添上我。</p><p class="poem-stanza">松江海印精舍道人不眠中夜起，小立莓苔地。</p><p class="poem-stanza">九枝灯上花，四塔庭前桧，梅窗月明清似水。</p><p class="poem-stanza">永嘉泛湖秋云锦香招画船，一步一个描金扇。</p><p class="poem-stanza">花前北海樽，湖上西施面，登楼有谁思惠远？次必庵赵万户韵岩扃带云长是掩，不许猿鹤占。</p><p class="poem-stanza">《黄庭》尽日观，白发无心染，研朱又将《周易》点。</p><p class="poem-stanza">老王将军纶巾紫髯风满把，老向辕门下。</p><p class="poem-stanza">霜明宝剑花，尘暗银鞍帕，江边草青闲战马。</p><p class="poem-stanza">春情园林且休题杜宇，未了吟春句。</p><p class="poem-stanza">残花酒醒时，芳草人归处，东风小楼听夜雨。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
